/*
 * Hand-written convenience helpers. This file is not generated by Speakeasy.
 *
 * import { collectSVGs, unwrap } from "@quiverai/sdk/helpers";
 */

import { bytesToBase64, stringToBase64 } from "./lib/base64.js";
import { EventStream } from "./lib/event-streams.js";
import {
  ImageInputReferenceInput,
  PublicErrorEnvelope,
  SvgInputReference,
  SvgStreamEvent,
} from "./sdk/models/shared/index.js";

/**
 * Thrown by {@link unwrap} and {@link collectSVGs} when the API answers with
 * an error envelope, or when a stream ends with an `error` event.
 */
export class APIError extends Error {
  /** Machine-readable error code, e.g. `insufficient_credits`. */
  readonly code: string;
  /** HTTP status code. */
  readonly status: number;
  /** Request identifier to quote when contacting support. */
  readonly requestId: string;
  /** The request parameter the failure is about, when there is one. */
  readonly param: string | undefined;
  /** Seconds to wait before retrying, when the API provides it. */
  readonly retryAfter: number | undefined;

  constructor(error: {
    code: string;
    message: string;
    status: number;
    requestId: string;
    param?: string | undefined;
    retryAfter?: number | undefined;
  }) {
    super(error.message);
    this.name = "APIError";
    this.code = error.code;
    this.status = error.status;
    this.requestId = error.requestId;
    this.param = error.param;
    this.retryAfter = error.retryAfter;
  }
}

/** Returns true when a `result` is an API error envelope. */
export function isAPIError(value: unknown): value is PublicErrorEnvelope {
  if (
    typeof value !== "object" || value === null
    || value instanceof ReadableStream
  ) {
    return false;
  }
  const v = value as Record<string, unknown>;
  return typeof v["code"] === "string"
    && typeof v["message"] === "string"
    && typeof v["status"] === "number"
    && typeof v["requestId"] === "string";
}

/**
 * Returns the `result` of an SDK response, throwing an {@link APIError} when
 * it is an error envelope. The error envelope is removed from the return type.
 *
 * @example
 * const model = unwrap(await quiver.models.getModel({ model: "arrow-2" }));
 */
export function unwrap<T>(
  response: { result: T },
): Exclude<T, PublicErrorEnvelope> {
  const { result } = response;
  if (isAPIError(result)) {
    throw new APIError(result);
  }
  return result as Exclude<T, PublicErrorEnvelope>;
}

type SvgResult =
  | PublicErrorEnvelope
  | { data: Array<{ svg: string }> }
  | EventStream<SvgStreamEvent>;

export type CollectSVGsOptions = {
  /**
   * Called for every server-sent event when the request was made with
   * `stream: true`. Use it to render drafts or progress.
   */
  onEvent?: (event: SvgStreamEvent) => void;
};

/**
 * Resolves a generate, edit, animate or vectorize call to the final SVG
 * markup, one string per output. Works for both regular and `stream: true`
 * requests, and throws an {@link APIError} on failure.
 *
 * @example
 * const [svg] = await collectSVGs(
 *   quiver.createSVGs.generateSVG({
 *     generateSVGRequest: { model: "arrow-2", prompt: "A paper plane icon" },
 *   }),
 * );
 */
export async function collectSVGs(
  response: { result: SvgResult } | PromiseLike<{ result: SvgResult }>,
  options?: CollectSVGsOptions,
): Promise<string[]> {
  const result = unwrap(await response);
  if (!(result instanceof EventStream)) {
    return result.data.map((doc) => doc.svg);
  }

  // Outputs of a multi-output stream may interleave, so key them by id.
  const outputs = new Map<string, { index: number | undefined; svg: string }>();
  for await (const event of result) {
    options?.onEvent?.(event);
    if (event.event === "error") {
      throw new APIError(event.data);
    }
    if (event.event === "content" && event.data.type === "content") {
      outputs.set(event.data.id, {
        index: event.data.index,
        svg: event.data.svg,
      });
    }
  }

  return [...outputs.values()]
    .map((output, arrival) => ({ ...output, arrival }))
    .sort((a, b) => (a.index ?? a.arrival) - (b.index ?? b.arrival))
    .map((output) => output.svg);
}

const URL_PATTERN = /^https?:\/\//i;
const DATA_URL_PATTERN = /^data:[^,]*;base64,/i;

/**
 * Builds the `svgSource` for edit and animate requests from either a URL or
 * raw SVG markup.
 *
 * @example
 * svgSource: svgSource("<svg xmlns='http://www.w3.org/2000/svg'>...</svg>")
 */
export function svgSource(svg: string): SvgInputReference {
  const trimmed = svg.trim();
  return URL_PATTERN.test(trimmed)
    ? { url: trimmed }
    : { base64: stringToBase64(svg) };
}

/**
 * Builds an image reference (`image`, `references`) from a URL, a base64
 * data URL, or raw image bytes.
 *
 * @example
 * image: imageSource(await readFile("logo.png"))
 */
export function imageSource(
  image: string | Uint8Array | ArrayBuffer,
): ImageInputReferenceInput {
  if (typeof image !== "string") {
    return {
      base64: bytesToBase64(
        image instanceof Uint8Array ? image : new Uint8Array(image),
      ),
    };
  }
  const trimmed = image.trim();
  if (URL_PATTERN.test(trimmed)) {
    return { url: trimmed };
  }
  if (DATA_URL_PATTERN.test(trimmed)) {
    return { base64: trimmed.replace(DATA_URL_PATTERN, "") };
  }
  throw new TypeError(
    "imageSource expects an http(s) URL, a base64 data URL, or image bytes",
  );
}
